// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        vm.deal(address(c), 1e18);
        address nonOwner = address(0x1234);
        address recipient = address(0x4567);
        vm.deal(nonOwner, 0);
        bool ok;
        vm.prank(nonOwner);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false && address(c).balance == 1e18);
    }
}
